<?php
$pageTitle='Zakat Donation'; require_once '_header.php';
$userId=(int)$_SESSION['user_id'];$st=$pdo->prepare("SELECT c.id,c.reference_no FROM zakat_calculations c JOIN zakat_payments p ON p.calculation_id=c.id AND p.status='confirmed' WHERE c.user_id=? ORDER BY c.created_at DESC LIMIT 1");$st->execute([$userId]);$eligible=$st->fetch(PDO::FETCH_ASSOC);$message='';
if($_SERVER['REQUEST_METHOD']==='POST' && $eligible){$amount=(float)$_POST['amount'];$recipient=trim($_POST['recipient']??'');$note=trim($_POST['note']??'');if($amount<=0||$recipient==='')$message='Enter a valid amount and recipient.';else{$st=$pdo->prepare("INSERT INTO zakat_donations(user_id,amount,recipient,note) VALUES(?,?,?,?)");$st->execute([$userId,$amount,$recipient,$note]);addNotification($userId,'Donation request submitted','Your donation request has been recorded.');logActivity($userId,'donation',(int)$pdo->lastInsertId(),'Created a Zakat donation request');$message='Donation request submitted successfully.';}}
?>
<div class="max-w-2xl mx-auto"><div class="mb-7"><h1 class="text-2xl font-bold">Zakat Donation</h1><p class="text-slate-500 text-sm mt-1">Record a donation after your Zakat has been confirmed.</p></div>
