<?php else:?><div class="bg-white border rounded-2xl p-6"><div class="bg-emerald-50 rounded-xl p-4 mb-5 text-sm text-emerald-800">Confirmed calculation: <b><?=e($eligible['reference_no'])?></b></div><?php if($message):?><div class="mb-4 p-3 rounded-xl bg-green-50 text-green-700"><?=$message?></div><?php endif;?><form method="POST" class="space-y-4"><div><label class="block text-sm font-semibold mb-2">Donation amount (₦)</label><input name="amount" type="number" min="1" step=".01" required class="w-full border rounded-xl px-4 py-3"></div><div><label class="block text-sm font-semibold mb-2">Recipient / organization</label><input name="recipient" required class="w-full border rounded-xl px-4 py-3" placeholder="Who should receive the donation?"></div><div><label class="block text-sm font-semibold mb-2">Note (optional)</label><textarea name="note" rows="4" class="w-full border rounded-xl px-4 py-3"></textarea></div><p class="text-xs text-slate-500">This records a donation request in ZakatPro. It does not represent a real fund transfer unless a payment process is connected.</p><button class="w-full bg-emerald-700 text-white py-3 rounded-xl font-semibold">Submit Donation Request</button></form></div><?php endif;?></div>
